# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: shape
def shape(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return shape(render(fold(gather(digest(raw)))))

